const input = $input.first().json;
const body = input.body || input;

const proposalId = `PROP-${Date.now().toString(36).toUpperCase()}`;
const now = new Date();
const validUntil = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000); // 30 days

// Calculate totals
const lineItems = body.line_items || [];
const subtotal = lineItems.reduce((sum, item) => sum + (item.quantity * item.unit_price), 0);
const discount = body.discount_percent ? subtotal * body.discount_percent / 100 : (body.discount_amount || 0);
const taxRate = body.tax_rate || 11; // PPN 11%
const taxAmount = (subtotal - discount) * taxRate / 100;
const total = subtotal - discount + taxAmount;

return [{
  json: {
    proposal_id: proposalId,
    deal_id: body.deal_id,
    client_id: body.client_id,
    contact_email: body.contact_email,
    contact_name: body.contact_name,
    company_name: body.company_name,

    // Proposal details
    title: body.title || `Proposal for ${body.company_name}`,
    description: body.description || '',
    line_items: lineItems.map(item => ({
      ...item,
      total: item.quantity * item.unit_price
    })),

    // Financials
    currency: body.currency || 'IDR',
    subtotal: subtotal,
    discount: discount,
    discount_percent: body.discount_percent || 0,
    tax_rate: taxRate,
    tax_amount: taxAmount,
    total: total,

    // Terms
    payment_terms: body.payment_terms || 'Net 30',
    valid_until: validUntil.toISOString().split('T')[0],
    terms_conditions: body.terms || 'Standard terms and conditions apply.',

    // Meta
    created_at: now.toISOString(),
    created_by: body.created_by || 'system',
    status: 'draft'
  }
}];
